"use client";

import { useRef, useState } from "react";

export function RangeSliderTailwind({ min = 0, max = 1000, step = 10 }) {
  const [vals, setVals] = useState([200, 800]);
  const [active, setActive] = useState<number | null>(null);
  const track = useRef<HTMLDivElement>(null);
  const pct = (v: number) => ((v - min) / (max - min)) * 100;
  const set = (i: number, raw: number) => { const v = Math.round(raw / step) * step; const n = [...vals]; n[i] = Math.min(i ? max : n[1], Math.max(i ? n[0] : min, v)); setVals(n); };
  const at = (x: number) => { const r = track.current!.getBoundingClientRect(); return min + ((x - r.left) / r.width) * (max - min); };
  return (
    <div className="w-full max-w-md space-y-3 text-zinc-100">
      <div className="flex justify-between text-sm"><span className="font-medium">Price range</span><span className="text-zinc-400">${vals[0]} – ${vals[1]}</span></div>
      <div ref={track} className="relative mt-7 flex h-8 touch-none items-center" onPointerDown={(e) => { const r = at(e.clientX); const i = Math.abs(r - vals[0]) <= Math.abs(r - vals[1]) ? 0 : 1; setActive(i); e.currentTarget.setPointerCapture(e.pointerId); set(i, r); }} onPointerMove={(e) => active !== null && e.buttons && set(active, at(e.clientX))} onPointerUp={() => setActive(null)}>
        <div className="relative h-1.5 w-full overflow-hidden rounded-full bg-zinc-800"><div className="absolute inset-y-0 bg-indigo-500" style={{ left: `${pct(vals[0])}%`, width: `${pct(vals[1]) - pct(vals[0])}%` }} /></div>
        {vals.map((v, i) => (
          <div key={i} role="slider" tabIndex={0} aria-label={i ? "Maximum price" : "Minimum price"} aria-valuemin={i ? vals[0] : min} aria-valuemax={i ? max : vals[1]} aria-valuenow={v} onKeyDown={(e) => { if (e.key === "ArrowRight") set(i, v + step); if (e.key === "ArrowLeft") set(i, v - step); }} className="absolute top-1/2 size-5 -translate-x-1/2 -translate-y-1/2 rounded-full border-2 border-indigo-500 bg-white shadow transition-transform data-[a=true]:scale-110" data-a={active === i} style={{ left: `${pct(v)}%` }}>
            {active === i && <span className="absolute bottom-full left-1/2 mb-2.5 -translate-x-1/2 rounded-md bg-indigo-500 px-2 py-1 text-xs font-semibold text-white">${v}</span>}
          </div>
        ))}
      </div>
    </div>
  );
}
